          annotationRef.current.remove();
        } catch {
          // ignore cleanup errors
        }
        annotationRef.current = null;
      }
    };
  }, [
    inView,
    color,
    strokeWidth,
    paddingX,
    paddingY,
    animationDuration,
    animate,
    iterations,
    animationDelay,
    children,
  ]);

  return (
    <span
      ref={elementRef}
      className={`relative inline-block ${className}`}
    >
      <span className={`relative z-10 ${textClassName}`}>{children}</span>
    </span>
  );
